import { createTheme } from '@mui/material';

const theme = createTheme({
  components: {
    MuiCssBaseline: {
      styleOverrides: {
        '*': {
          boxSizing: 'border-box',//paddingやborderを含めて指定したサイズ内にレイアウトを収めるためにboxSizing: 'border-box'を設定
        },
        '*::before': {
          boxSizing: 'border-box',
        },
        '*::after': {
          boxSizing: 'border-box',
        },
      },
    },
    MuiOutlinedInput: {
      styleOverrides: {
      root: {
        '&.Mui-focused .MuiOutlinedInput-notchedOutline': {
          borderWidth: 2, // ← フォーカスで少し太く
        },
      },
    },
  },
  },
});

export default theme;
